import { test, expect, type Page } from '@playwright/test';

const VERIFY_400 = JSON.stringify({ code: 400, error_code: 'otp_expired', msg: 'Token has expired or is invalid' });

// Ячейки кода: листовые элементы с «–» или цифрой в одном ряду; порядок — по x слева направо, «–» → ''.
async function readCells(page: Page): Promise<string[]> {
  return page.evaluate(() => {
    const leaf = [...document.querySelectorAll('div')].filter((e) => e.childElementCount === 0 && /^(–|\d)$/.test((e.textContent || '').trim()));
    if (!leaf.length) return [];
    const row = leaf[0].parentElement;
    return leaf
      .filter((e) => e.parentElement === row)
      .map((e) => ({ t: (e.textContent || '').trim(), x: e.getBoundingClientRect().x }))
      .sort((a, b) => a.x - b.x)
      .map((c) => (c.t === '–' ? '' : c.t));
  });
}

async function loginToPhone(page: Page) {
  await page.goto('/welcome');
  await page.getByRole('button', { name: 'כבר יש לי חשבון? התחברות' }).click();
  await page.waitForURL(/\/phone/);
}

async function phoneToOtp(page: Page) {
  await page.getByRole('textbox', { name: '50-000-0000' }).pressSequentially('501234567');
  await Promise.all([page.waitForURL(/\/otp/), page.getByText('שליחת קוד').click()]);
  await expect(page.getByText('מה הקוד שקיבלת?')).toBeVisible();
  await expect.poll(() => readCells(page)).toEqual(['', '', '', '', '', '']);
}

async function typeDigits(page: Page, digits: string) {
  await page.locator('input').first().focus();
  for (const d of digits) await page.keyboard.type(d);
}

test.describe('Вход/регистрация — телефон и OTP', () => {
  test('OTP: вставка 6 цифр сохраняет порядок @iphone @prod-safe (#5fb42e)', async ({ page }) => {
    // 1. Перехватить otp → 200; verify — ответ 400 задерживается до сигнала из теста.
    let release!: () => void;
    const gate = new Promise<void>((r) => (release = r));
    await page.route('**/auth/v1/otp*', (r) => r.fulfill({ status: 200, contentType: 'application/json', body: '{}' }));
    await page.route('**/auth/v1/verify*', async (r) => {
      await gate;
      await r.fulfill({ status: 400, contentType: 'application/json', body: VERIFY_400 });
    });

    try {
      // 2. Дойти до /otp, вставить «123456» (фокус + insertText = вставка).
      await loginToPhone(page);
      await phoneToOtp(page);
      await page.locator('input').first().focus();

      // 3. Дождаться запроса verify.
      const [verifyReq] = await Promise.all([page.waitForRequest('**/auth/v1/verify*'), page.keyboard.insertText('123456')]);
      expect(verifyReq.postDataJSON().token).toBe('123456');

      // До ответа verify ячейки слева направо «1 2 3 4 5 6».
      await expect.poll(() => readCells(page)).toEqual(['1', '2', '3', '4', '5', '6']);
    } finally {
      // Отпустить ответ 400.
      release();
    }
    await expect(page.getByText('הקוד שגוי או שפג תוקפו')).toBeVisible();
  });
});
